def backfill_campaign_run_times(apps, schema_editor):
    """Approximate run-time marks for campaigns created before they were tracked.

    Earlier campaigns went live at creation, so ``created_at`` is the best
    available activation time; ended campaigns use their last update. Goal
    fields were not writable before, but inconsistent pairs are cleared so the
    new range constraints can be added.
    """
    Campaign = apps.get_model('employers', 'RecruitmentCampaign')
    Campaign.objects.filter(status__in=['active', 'paused', 'completed']).update(
        first_activated_at=F('created_at'), activated_at=F('created_at')
    )
    Campaign.objects.filter(status__in=['completed', 'cancelled']).update(
        ended_at=F('updated_at'), ended_by='user'
    )
    Campaign.objects.filter(target_date__lt=F('start_date')).update(target_date=None)
    Campaign.objects.filter(budget_max__lt=F('budget_min')).update(budget_max=None)


